---刷新cell
---@param data table cell数据
---@param index integer cell序号
---@param cb function 加入按钮点击回调
function OverseaChatClubRecruitPanelCell:RefreshCell(data, index, cb)
    self._index = checkInt(index)
    self._cb = cb
    CfUtils.FillText(self.TextDesc, localize("社团招募"))

    CfUtils.FillText(self.ClubLevel, localize("_level_级",{_level_ = data.level}))
    CfUtils.FillText(self.ClubPeople,localize("人数：_num1_/_num2_",{_num1_ = data.memberNum,_num2_ = data.memberNumLimit}))

    CfUtils.SetActive(self.TxtInstructions,true)
    if checkNumber(data.applyPermission.type) > 0 then
        CfUtils.FillText(self.TxtInstructions,localize("_level_级以上，需要审核",{_level_ = data.applyPermission.levelLimit }))
    else
        CfUtils.FillText(self.TxtInstructions,localize("_level_级以上，不需要审核",{_level_ = data.applyPermission.levelLimit }))
    end

    CfUtils.FillText(self.TextClubName,data.name)

    local clubHeadVo = ClubUtils.GetClubHeadVo(data.avatar)
    CfUtils.FillImage(self.ImgClubHead, clubHeadVo.photoPath)

    if checkNumber(data.memberNum) == data.memberNumLimit then
        CfUtils.SetActive(self.JoinBtn.gameObject,false)
        CfUtils.SetActive(self.StatusTextDesc.gameObject,true)
    else
        CfUtils.SetActive(self.JoinBtn.gameObject,true)
        CfUtils.SetActive(self.StatusTextDesc.gameObject,false)
    end

--[[    if data.isApplied then
